        if(!class_exists('TCPDF'))require_once __DIR__.'/../vendor/tecnickcom/tcpdf/tcpdf.php';$pdf=new class extends TCPDF {public function __construct(){parent::__construct('P','mm','A4',true,'UTF-8',false,false);$this->tcpdflink=false;}};$pdf->setPrintHeader(false);$pdf->setPrintFooter(false);$pdf->setMargins(15,15,15);$pdf->setAutoPageBreak(true,15);$pdf->setFont('dejavusans','',9);$pdf->setCreator('CRM');$pdf->setAuthor($data['identity']['legal_name']);$pdf->setTitle($data['number']);$pdf->AddPage();$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$html=($data['identity']['logo_inline']!==''?'<img width="110" src="'.$e($data['identity']['logo_inline']).'"><br>':'').'<h1>Nota de crédito '.$e($data['number']).'</h1><p>Estado: '.([1=>'Disponível',2=>'Consumida',3=>'Cancelada'][$data['status']]).'</p><p>'.$e($data['identity']['legal_name']).'<br>'.$e($data['identity']['tax_id']).'<br>'.$e($data['identity']['address']).'<br>'.$e($data['identity']['city'].' / '.$data['identity']['state']).'</p><p>Destinatário: '.$e($data['recipient']['name']).'<br>'.$e($data['recipient']['tax_id']).'<br>Emissão: '.$e($data['date']).'</p><table cellpadding="4"><tr><th>Descrição</th><th>Quantidade</th><th>Preço unitário</th></tr>';
